import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import { ref, computed, onMounted } from 'vue';
export default {
  name: 'InvitationToBid',
  setup() {
    // State
    const invitations = ref([{
      id: 1,
      projectName: 'Office Renovation Project',
      description: 'Complete renovation of the main office building including electrical, plumbing, and interior design work.',
      deadline: new Date('2024-02-15T17:00:00'),
      status: 'Open',
      createdAt: new Date('2024-01-01T09:00:00')
    }, {
      id: 2,
      projectName: 'IT Equipment Procurement',
      description: 'Purchase of computers, servers, and networking equipment for the new branch office.',
      deadline: new Date('2024-02-20T17:00:00'),
      status: 'Pending',
      createdAt: new Date('2024-01-05T10:30:00')
    }, {
      id: 3,
      projectName: 'Security System Installation',
      description: 'Installation of CCTV cameras, access control systems, and alarm systems across all facilities.',
      deadline: new Date('2024-01-30T17:00:00'),
      status: 'Closed',
      createdAt: new Date('2023-12-15T14:00:00')
    }]);
    const searchQuery = ref('');
    const isViewing = ref(false);
    const isEditing = ref(false);
    const isDeleting = ref(false);
    const selectedInvitation = ref(null);
    const deleteId = ref(null);
    const editForm = ref({
      projectName: '',
      description: '',
      deadline: '',
      status: 'Open'
    });

    // Computed
    const filteredInvitations = computed(() => {
      if (!searchQuery.value.trim()) {
        return invitations.value;
      }
      const query = searchQuery.value.toLowerCase();
      return invitations.value.filter(invitation => invitation.projectName.toLowerCase().includes(query) || invitation.description.toLowerCase().includes(query) || invitation.status.toLowerCase().includes(query));
    });

    // Methods
    const formatDate = date => {
      if (!date) return 'N/A';
      return new Date(date).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    };
    const truncateText = (text, maxLength) => {
      if (!text) return 'N/A';
      return text.length > maxLength ? text.substring(0, maxLength) + '...' : text;
    };
    const getStatusClass = status => {
      switch (status?.toLowerCase()) {
        case 'open':
          return 'status-open';
        case 'closed':
          return 'status-closed';
        case 'pending':
          return 'status-pending';
        default:
          return 'status-default';
      }
    };

    // Modal handlers
    const handleView = invitation => {
      selectedInvitation.value = invitation;
      isViewing.value = true;
    };
    const closeViewModal = () => {
      isViewing.value = false;
      selectedInvitation.value = null;
    };
    const handleEdit = invitation => {
      selectedInvitation.value = invitation;
      editForm.value = {
        projectName: invitation.projectName,
        description: invitation.description,
        deadline: new Date(invitation.deadline).toISOString().slice(0, 16),
        status: invitation.status
      };
      isEditing.value = true;
    };
    const openEditModal = () => {
      closeViewModal();
      isEditing.value = true;
    };
    const closeEditModal = () => {
      isEditing.value = false;
      selectedInvitation.value = null;
      editForm.value = {
        projectName: '',
        description: '',
        deadline: '',
        status: 'Open'
      };
    };
    const handleEditSubmit = () => {
      if (selectedInvitation.value) {
        const index = invitations.value.findIndex(inv => inv.id === selectedInvitation.value.id);
        if (index !== -1) {
          invitations.value[index] = {
            ...invitations.value[index],
            projectName: editForm.value.projectName,
            description: editForm.value.description,
            deadline: new Date(editForm.value.deadline),
            status: editForm.value.status
          };
        }
      }
      closeEditModal();
    };
    const handleDelete = id => {
      deleteId.value = id;
      isDeleting.value = true;
    };
    const openDeleteModal = () => {
      deleteId.value = selectedInvitation.value.id;
      closeViewModal();
      isDeleting.value = true;
    };
    const closeDeleteModal = () => {
      isDeleting.value = false;
      deleteId.value = null;
    };
    const confirmDelete = () => {
      if (deleteId.value) {
        invitations.value = invitations.value.filter(inv => inv.id !== deleteId.value);
      }
      closeDeleteModal();
    };
    const openCreateModal = () => {
      // This would open a create modal - for now just show an alert
      alert('Create invitation modal would open here');
    };
    return {
      invitations,
      searchQuery,
      filteredInvitations,
      isViewing,
      isEditing,
      isDeleting,
      selectedInvitation,
      editForm,
      formatDate,
      truncateText,
      getStatusClass,
      handleView,
      closeViewModal,
      handleEdit,
      openEditModal,
      closeEditModal,
      handleEditSubmit,
      handleDelete,
      openDeleteModal,
      closeDeleteModal,
      confirmDelete,
      openCreateModal
    };
  }
};
